const clamp = (v, min, max) => Math.min(Math.max(v, min), max);
const lerp = (a, b, t) => a + (b - a) * clamp(t, 0, 1);
const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
const easeInOutCubic = (t) => {
  const c = clamp(t, 0, 1);
  return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
};
const windowEase = (time, t0, t1, easing = easeOutCubic) => {
  if (t1 <= t0) return time >= t1 ? 1 : 0;
  const progress = clamp((time - t0) / (t1 - t0), 0, 1);
  return easing(progress);
};

const DEFAULT_PRIMARY_PHRASE = 'A year from now you will wish you had started';
const DEFAULT_SECONDARY_WORD = 'today';

function render(options) {
  const {
    ctx,
    width: W,
    height: H,
    localT,
    dur,
    beatPulse,
    currentBeat,
    scene,
    style,
  } = options;

  const safeDur = Math.max(0.1, dur);
  const p = clamp(localT / safeDur, 0, 1);
  const safePulse = Number.isFinite(beatPulse) ? clamp(beatPulse, 0, 1) : 0;
  const safeBeat = Number.isFinite(currentBeat) ? currentBeat : 0;

  const fontFamily = (style && style.typography && style.typography.fontFamily) || 'Inter, -apple-system, sans-serif';
  const strokeColor = '#ffffff';
  const goldCoreColor = '#ffcc00';

  const rawPrimary =
    scene && scene.lyricPrimary && scene.lyricPrimary.trim().length > 0
      ? scene.lyricPrimary.trim()
      : DEFAULT_PRIMARY_PHRASE;
  const words = rawPrimary.split(/\s+/);
  const wordCount = Math.max(2, words.length);

  const terminalWord =
    scene && scene.lyricSecondary && scene.lyricSecondary.trim().length > 0
      ? scene.lyricSecondary.trim()
      : DEFAULT_SECONDARY_WORD;

  ctx.save();

  // 1. Pure Pitch-Black Void
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, W, H);

  // 2. Compute World-Space Horizontal Layout for Words
  const totalSpanW = W * 0.84;
  const startX = W * 0.08;
  const baselineY = H * 0.49;
  const fontSize = Math.max(12, Math.round(W * 0.033));

  ctx.font = `500 ${fontSize}px ${fontFamily}`;
  ctx.textBaseline = 'alphabetic';

  const rawWeights = words.map((w) => Math.max(1.4, w.length * 0.85));
  const totalWeight = rawWeights.reduce((acc, v) => acc + v, 0);

  const wordLayouts = [];
  let cursorX = startX;
  const chainPhaseEnd = 0.42;

  for (let i = 0; i < words.length; i++) {
    const sliceW = (rawWeights[i] / totalWeight) * totalSpanW;
    const xCenter = i === 0 ? startX + sliceW * 0.25 : cursorX + sliceW * 0.5;
    const approxTextW = words[i].length * fontSize * 0.54;
    const stepDur = chainPhaseEnd / wordCount;
    const revealStart = i * stepDur * 0.88;
    const revealEnd = revealStart + stepDur * 1.12;

    wordLayouts.push({
      text: words[i],
      xCenter,
      xLeft: xCenter - approxTextW * 0.5,
      xRight: xCenter + approxTextW * 0.5,
      width: approxTextW,
      revealStart,
      revealEnd,
    });

    cursorX += sliceW;
  }

  const originX = wordLayouts[0].xCenter;
  const lastWordX = wordLayouts[wordLayouts.length - 1].xCenter;
  const arcAnchorY = baselineY - fontSize * 1.05;

  const lowerArcStartY = baselineY + fontSize * 0.55;
  const lowerArcRadiusX = (lastWordX - originX) * 0.42;
  const lowerArcRadiusY = lowerArcRadiusX * 0.92;
  const todayRightX = lastWordX - lowerArcRadiusX;
  const todayY = lowerArcStartY + lowerArcRadiusY;
  const todayApproxW = terminalWord.length * fontSize * 0.56;
  const todayCenterX = todayRightX - todayApproxW * 0.58;

  // 3. Multi-Stage 2D Camera Choreography
  const camTrackProgress = windowEase(p, 0.0, 0.42, easeInOutCubic);
  const camDownProgress = windowEase(p, 0.40, 0.54, easeInOutCubic);
  const camPullbackProgress = windowEase(p, 0.58, 0.70, easeInOutCubic);

  const trackingFocusX = lerp(originX + W * 0.12, lastWordX - W * 0.08, camTrackProgress);
  const trackingFocusY = baselineY - H * 0.02;

  const downFocusX = todayCenterX + W * 0.06;
  const downFocusY = todayY - H * 0.02;

  const masterFocusX = W * 0.5;
  const masterFocusY = baselineY - H * 0.01;

  const preMasterX = lerp(trackingFocusX, downFocusX, camDownProgress);
  const preMasterY = lerp(trackingFocusY, downFocusY, camDownProgress);
  const camFocusX = lerp(preMasterX, masterFocusX, camPullbackProgress);
  const camFocusY = lerp(preMasterY, masterFocusY, camPullbackProgress);

  const closeZoom = lerp(2.15, 1.95, camDownProgress);
  const baseZoom = lerp(closeZoom, 1.0, camPullbackProgress);
  const reactiveZoom = baseZoom * (1 + safePulse * 0.015);

  ctx.translate(W * 0.5, H * 0.5);
  ctx.scale(reactiveZoom, reactiveZoom);
  ctx.translate(-camFocusX, -camFocusY);

  // 4. Render Upper Concentric Semicircular Arcs
  const baseLineWidth = Math.max(1.5, W * 0.0028);

  for (let i = 1; i < wordLayouts.length; i++) {
    const targetWord = wordLayouts[i];
    const arcProgress = windowEase(
      p,
      targetWord.revealStart,
      targetWord.revealEnd,
      easeInOutCubic
    );

    if (arcProgress <= 0.001) continue;

    const cxArc = (originX + targetWord.xCenter) * 0.5;
    const radiusArc = Math.max(1, (targetWord.xCenter - originX) * 0.5);
    const startAngle = Math.PI;
    const endAngle = Math.PI + Math.PI * arcProgress;

    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = baseLineWidth;
    ctx.lineCap = 'round';
    ctx.globalAlpha = clamp(arcProgress * 1.5, 0, 1);

    ctx.beginPath();
    ctx.arc(cxArc, arcAnchorY, radiusArc, startAngle, endAngle, false);
    ctx.stroke();
    ctx.restore();
  }

  // 5. Render Horizontal Words
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';

  for (let i = 0; i < wordLayouts.length; i++) {
    const wl = wordLayouts[i];
    const wordProgress = windowEase(p, wl.revealStart, wl.revealEnd, easeOutCubic);
    if (wordProgress <= 0.001) continue;

    const chars = wl.text.split('');
    const charCount = Math.max(1, chars.length);
    const charSpacing = wl.width / charCount;
    const wordStartX = wl.xCenter - wl.width * 0.5 + charSpacing * 0.5;

    for (let c = 0; c < chars.length; c++) {
      const charDelay = (c / charCount) * 0.35;
      const localCharP = clamp((wordProgress - charDelay) / (1 - charDelay), 0, 1);
      const charEase = easeOutCubic(localCharP);

      if (charEase <= 0.01) continue;

      const dropDirection = c === chars.length - 1 ? 1 : 0.35;
      const yOffset = (1 - charEase) * fontSize * 0.42 * dropDirection;

      ctx.save();
      ctx.font = `500 ${fontSize}px ${fontFamily}`;
      ctx.fillStyle = strokeColor;
      ctx.globalAlpha = charEase;
      ctx.fillText(chars[c], wordStartX + c * charSpacing, baselineY + yOffset);
      ctx.restore();
    }
  }

  // 6. Render Lower Return Sweep Arc
  const lowerArcProgress = windowEase(p, 0.41, 0.51, easeInOutCubic);
  if (lowerArcProgress > 0.001) {
    ctx.save();
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = baseLineWidth;
    ctx.lineCap = 'round';
    ctx.globalAlpha = clamp(lowerArcProgress * 1.4, 0, 1);

    const segments = 48;
    const activeSegments = Math.max(1, Math.round(segments * lowerArcProgress));
    ctx.beginPath();
    for (let s = 0; s <= activeSegments; s++) {
      const frac = (s / segments) * (Math.PI * 0.5);
      const px = todayRightX + Math.cos(frac) * lowerArcRadiusX;
      const py = lowerArcStartY + Math.sin(frac) * lowerArcRadiusY;
      if (s === 0) {
        ctx.moveTo(px, py);
      } else {
        ctx.lineTo(px, py);
      }
    } 
    ctx.stroke();
    ctx.restore();
  }

  // 7. Render Clean, Crisp Golden Terminal Word
  const todayProgress = windowEase(p, 0.48, 0.56, easeOutCubic);
  if (todayProgress > 0.001) {
    ctx.save();
    ctx.font = `600 ${Math.round(fontSize * 1.08)}px ${fontFamily}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.globalAlpha = todayProgress;
    ctx.fillStyle = goldCoreColor;
    ctx.shadowColor = 'rgba(255, 204, 0, 0.35)';
    ctx.shadowBlur = 4;

    const todayYOffset = (1 - todayProgress) * fontSize * 0.25;
    ctx.fillText(terminalWord, todayCenterX, todayY + todayYOffset);
    ctx.restore();
  }

  ctx.restore();
}
